quests[52654] = { id = 52654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegskampagne", description = "{name}, schenkt mir einen Moment Eurer Zeit.\n\nBevor Ihr Boralus verlasst, solltet Ihr mit dem Hochkommandanten der 7. Legion Halford Wyrmbann sprechen. Er hat nach Euch persönlich verlangt.\n\nIhr findet ihn auf der Erlösenden Winde. Sie sollte sich draußen direkt am ersten Liegeplatz befinden.", sourceObjective = "Meldet Euch bei Halford Wyrmbann an Bord der Erlösenden Winde.", completion = "Ah, {name}. Schön, Euch wiederzusehen.\n\nAuf uns wartet Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
