quests[52745] = { id = 52745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yuke braucht Hilfe!" }
quests[52746] = { id = 52746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegsvorrat", description = "Als Allererstes: Vergesst nie... wir sind im Krieg.\n\nNur weil die Zandalari an unserer Seite kämpfen, haben wir noch nichts erreicht. Irgendwann müssen wir die Allianz zerschmettern.\n\nIhr werdet mit mir die Operationen in Kul Tiras leiten. Aber dafür brauchen wir erst Ressourcen.", sourceObjective = "Sammelt 100 Kriegsressourcen. Kriegsressourcen können von vielen unterschiedlichen Quellen beschafft werden, darunter über Quests und Schatztruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52748] = { id = 52748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Blick auf den Himmel", description = "Ihr habt bei Kua'fon große Fortschritte gemacht. Er kann zwar noch nich' flieg'n, is' aber gesund un' wächst.\n\nBaut weiter auf dem Erfolg auf, {name}. Lasst Euch nich' von Pa'kus Lektion entmutig'n.\n\nMacht einfach weiter wie bisher. Versorgt Kua'fon, lasst ihn weiter Vertrau'n in seine Flügel gewinn'. Zeigt ihm, wie er vorankommt, dann werdet Ihr 'ne engere Verbindung krieg'n, als Ihr Euch erhoff'n würdet.\n\nWir versuchen's erneut, wenn seine Flügel Euch Schatten biet'n könn'.", sourceObjective = "Kümmert Euch um Kua'fon, bis er ausgewachsen ist.", completion = "<Kua'fon breitet seine prachtvollen Flügel aus.>\n\nSkrii!", sourceObjectiveStatus = "unverified-source-field" }
quests[52749] = { id = 52749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegskampagne", description = "{name}, schenkt mir einen Moment Eurer Zeit.\n\nBevor Ihr die Stadt verlasst, solltet Ihr mit mir zu den Docks zur Klagelied gehen. Ich muss mit Euch über den Krieg gegen die Allianz sprechen.", sourceObjective = "Meldet Euch bei Nathanos Pestrufer an Bord der Klagelied in Zuldazar.", completion = "Da seid Ihr ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[52750] = { id = 52750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewaffnete Bauern", description = "Ich hatte auf einen Trupp der Besten aus der Prachtmeerakademie gehofft, aber ich muss mich wohl mit Euch zufriedengeben.\n\nDie fehlenden Truppen gleichen wir mit unserem Mut wieder aus! Selbst die Bauern hier geben ihr Land nicht ohne Kampf auf.\n\nBringt die Tapfersten unter ihnen her. Gemeinsam mit unseren Marinesoldaten werden sie mehr ausrichten als allein auf den Feldern!", sourceObjective = "Rekrutiert 6 Bauern der Wachkuppe für die Miliz.", completion = "Wir werden Paare aus Freiwilligen und Soldaten bilden, um ihnen eine echte Chance zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[52751] = { id = 52751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsam aussehende Hunde", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52752] = { id = 52752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsame Ausgucke" }
quests[52754] = { id = 52754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sumpfbewohner", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
