quests[52757] = { id = 52757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzsteinverbrechen" }
quests[52760] = { id = 52760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasse Angelegenheit" }
quests[52761] = { id = 52761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung von Boralus: Blutgeld" }
quests[52762] = { id = 52762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fremdenführer", description = "Ich war lange Zeit Gast des Hafenmeisters und habe einige Dinge über Finn Schönwind gelernt. Wenn irgendjemand Euch dabei helfen kann, Hinweisen in Freihafen schnell nachzugehen, dann wird er es sein.\n\nFinn arbeitet für Carsten und befindet sich im Büro des Hafenmeisters. Zeigt ihm den Vertrag und rekrutiert ihn für uns. Beeilt Euch, {name}.", sourceObjective = "Findet Finn Schönwind im Büro des Hafenmeisters in Boralus.", completion = "Ich hatte gehofft, dass wir im Kleingedruckten etwas über Lady Jainas Standort erfahren würden, aber das Glück war uns nicht hold. Ich kann bestätigen, dass Aschenwind mit den Eisenfluträubern Geschäfte macht. Also gehen wir wohl nach Freihafen. Schon wieder.\n\nWelch Freude.", sourceObjectiveStatus = "unverified-source-field" }
quests[52763] = { id = 52763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung von Boralus: Die Reihen lichten" }
quests[52764] = { id = 52764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise mitten ins Nirgendwo", description = "Unser Gezeitenweiser, Thomas Zelling, behauptet, Wrackteile von Marschall Valentins Schiff gefunden zu haben.\n\nHat ja auch lange genug gedauert.\n\nMarschall Valentins Leichnam ist das letzte Teil, das zu unserem Plan fehlt, und er liegt in dem Schiffswrack. Wenn Ihr bereit seid, lasst uns zu seiner Ruhestätte aufbrechen.", sourceObjective = "Sprecht mit Schreckensadmiralin Segelriss und segelt zum Großen Meer.", completion = "Hier ist die Stelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[52765] = { id = 52765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefe tauchen", description = "Ihr müsst für uns Marschall M. Valentins Leichnam vom Meeresgrund unter uns bergen.\n\nIch muss Euch warnen: dieser Bereich des Meeres ist sehr tief und sehr dunkel und sehr kalt.\n\nSprecht mit Hobart auf der Backbordseite des Schiffs. Er hat die Maschinen dabei, die Ihr braucht, um zum Meeresgrund zu gelangen.", sourceObjective = "Sprecht mit Hobart Wurfhammer, um zum Meeresgrund zu tauchen und probiert dann Eure Stirnlampe aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[52766] = { id = 52766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wrack am Meeresboden", description = "<Rauschen>\n\n... Schiffswrack suchen...\n\n<Rauschen>\n\n... östlich...\n\n<Rauschen>", sourceObjective = "Soll wohl heißen, sucht nach einem Schiffswrack östlich von hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[52767] = { id = 52767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkennungsmarken überprüfen", description = "Ihr könnt Hobarts Stimme nicht mehr über das statische Rauschen hinweg hören.\n\nIn der Nähe könnt Ihr die Umrisse einiger im Wasser treibender Leichen erkennen. Sie sind schon stark verwest, doch ihre Erkennungsmarken sollten immer noch lesbar sein.\n\nHoffentlich können wir Marschall Valentin über seine Erkennungsmarke identifizieren.", sourceObjective = "Findet und identifiziert den Kapitän des Schiffswracks.", sourceObjectiveStatus = "unverified-source-field" }
quests[52768] = { id = 52768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der versunkene Friedhof", description = "<Rauschen>\n\n... Moment... mehr Wracks... \n\n<Rauschen>\n\n... ganz viele... Nordosten...\n\n<Rauschen>", sourceObjective = "Sucht nach weiteren Schiffswracks nordöstlich von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[52769] = { id = 52769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Kapitän nach dem anderen", description = "Offenbar seid Ihr allein.\n\nEs gibt noch mehr Schiffswracks am Meeresboden. Hier muss der Schauplatz einer gewaltigen Schlacht gewesen sein.\n\nZeit, die Hundemarken zu überprüfen, um Marschall Valentin zu finden.", sourceObjective = "Identifiziert die Kapitäne der drei Schiffe, die in der Nähe sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[52770] = { id = 52770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerviges Leuchten", description = "<Rauschen>\n\n... Probleme, Euch zu hören...\n\n<Rauschen>\n\n... elektrische Störung... biolumineszente Kreaturen...\n\n<Rauschen>\n\n... allmählich lästig...\n\n<Rauschen>", sourceObjective = "Tötet 10 biolumineszente Kreaturen, um Eure Kommunikationsprobleme mit Hobart zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52771] = { id = 52771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung von Boralus: Ketten brechen" }
quests[52772] = { id = 52772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Riff unterm Meer", description = "Da wir uns nun wieder hören können, lasst mich Euch erzählen, was hier oben los war.\n\nOffenbar haben wir meilenweit danebengelegen. Hat irgendwas mit unterseeischen Strömungen zu tun, Gezeiten der Zeit, blablabla. Ich glaube, Zelling ist ein wenig eingerostet.\n\nLange Rede, kurzer Sinn - Ihr seid nicht weit weg. Wir sind SICHER, dass Marschall Valentin direkt östlich von Euch in einem Schiffswrack am Rande eines Abgrunds ist. Zelling behauptet, dass da auch irgendetwas Großes ist, aber er kann nicht sagen, worum es sich handelt.", sourceObjective = "Findet Marschall Valentins Schiffswrack auf dem unterseeischen Felsvorsprung in der Nähe.", sourceObjectiveStatus = "unverified-source-field" }
quests[52773] = { id = 52773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasseratmender Drache", description = "Hm. Ein Drache sagt Ihr? Ich nehme an, das ergibt Sinn. Schließlich hat die Horde während des Zweiten Krieges rote Drachen in ihrer Armee eingesetzt, aber... na ja, wir reden nicht mehr viel darüber.\n\nTrotzdem ist Valentin auf dem Schiff. Ihr müsst auf die eine oder andere Weise an dem Drachen vorbei.", sourceObjective = "Tötet Daenistrasz.", sourceObjectiveStatus = "unverified-source-field" }
quests[52774] = { id = 52774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappen und rennen", description = "Dann müssen wir wohl diesen Marschall packen und an die Oberfläche bringen.\n\nObwohl ich finde, dass Ihr genauso gut das Schiffswrack nach anderen wertvollen Dingen durchsuchen könnt. Ihr habt so viel Zeit damit zugebracht, hier hinunter zu gelangen, und Zeit ist Geld.", sourceObjective = "Schnappt Euch Marschall M. Valentins Leichnam und den Leichnam des anderen Seemanns auf seinem Schiff.", completion = "<Nathanos betrachtet die Leichen der beiden Seeleute, zögert einen Moment und lacht dann.>\n\nIhr hattet nicht nur Erfolg, Ihr habt mir außerdem auch den Leichnam von Lady Prachtmeers erstgeborenem Sohn gebracht?! Ihr macht mir meine Aufgabe leicht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52775] = { id = 52775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung von Boralus: Was Euer ist, ist mein" }
quests[52776] = { id = 52776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Steinhauerwacht", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf die Steinhauerwacht geschickt.\n\nDarin wird erklärt, dass es ein schwer errungener Sieg war, der Außenposten jedoch gesichert wurde.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission ins Sturmsangtal?", completion = "Die Mission, im Sturmsangtal einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch sofort entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52777] = { id = 52777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Steinhauerwacht", description = "Der Überfall, den Ihr auf die Steinhauerwacht im Sturmsangtal geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zur Steinhauerwacht im Sturmsangtal und baut dort Befestigungsanlagen.\n\nDer Außenposten wird eine entscheidende Rolle in unserer Kampagne gegen die Allianz spielen.\n\nGeht mit Ehre!", sourceObjective = "Erobert die Steinhauerwacht für die Horde.", completion = "Seid gegrüßt, {name}. Hier ist ein ausgezeichneter Platz für einen Außenposten! Dank Eurer Führung hat die Horde einen weiteren Stützpunkt im Sturmsangtal!", sourceObjectiveStatus = "unverified-source-field" }
quests[52778] = { id = 52778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung von Boralus: Die Horde zerschmettern" }
quests[52779] = { id = 52779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krogg im Sumpf", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52780] = { id = 52780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Belagerung von Boralus: Die Allianz brechen" }
quests[52782] = { id = 52782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Sturmsangtal", description = "Wir haben zunehmende Hordenaktivität im Sturmsangtal festgestellt. Wir dürfen nicht zulassen, dass sie die Oberhand gewinnt.", sourceObjective = "Tötet Mitglieder der Horde im Sturmsangtal.", completion = "Großartige Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52784] = { id = 52784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordenschlächter", description = "Toll! Immer weiter so, <Soldat/Soldatin>!\n\nTötet ein paar mehr von der Horde, dann werdet Ihr in die Geschichtsbücher der Allianz eingehen.\n\nAber das wird nicht ganz leicht. Die Horde hat ein Kopfgeld auf Euch ausgesetzt, also seid vorsichtig!\n\nFür die Allianz!", sourceObjective = "Tötet 10 Anhänger der Horde, ohne zu sterben, während Ihr von der Horde gejagt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[52785] = { id = 52785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung von Zalamar" }
quests[52786] = { id = 52786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzschlächter", description = "Ja! Weiter so, tötet diese Allianztölen!\n\nWenn Ihr noch ein paar Allianzler tötet, könntet Ihr einen neuen Rekord aufstellen, {class}.\n\nAber das wird nicht leicht, denn die Allianz hat einen Preis auf Euren Kopf ausgesetzt! Passt auf Euch auf!\n\nFür die Horde!", sourceObjective = "Tötet 10 Anhänger der Allianz, ohne zu sterben, während ein Kopfgeld auf Euch ausgesetzt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[52787] = { id = 52787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmerzlinderung", description = "Die Sanitäter hier tun ihr Bestes, aber sie haben schwere Verluste erlitten und die medizinischen Vorräte werden immer knapper.\n\nMit ein paar Büscheln Immermoos könnte ich eine schmerzstillende Tinktur zusammenmischen, um die Leiden der Verwundeten zu lindern. Könntet Ihr bei den Bäumen in der Nähe ein wenig sammeln?\n\nIch muss Finns Zustand stabilisieren. Die Leute brauchen wirklich nicht noch einen Verwundeten, der vor Schmerzen brüllt.", sourceObjective = "Sammelt 5 Klumpen Immermoos.", progress = "Habt Ihr Immermoos gefunden?", completion = "Das sollte reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52788] = { id = 52788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keiner darf überleben", description = "Unser erster Angriff war ein Erfolg. Die Dunkeleisenzwerge halten die Stellung. Jetzt sind wir dran.\n\nIhr und ich müssen uns einen Weg durch diese Zandalari freikämpfen und sie auslöschen. Unsere Streitkräfte werden sich um die Verbleibenden kümmern.\n\nUnser Ziel ist es, ihre Streitkräfte zu schwächen und zwei wichtige Ziele auszumachen: den Schiffskapitän und seinen Berater.\n\nLasst uns gehen, {name}. Wenn wir hier versagen, waren alle unsere Bemühungen umsonst.", sourceObjective = "Tötet 10 Soldaten der Zandalari an Bord der Grals Ruf.", progress = "Wir haben keine Zeit zum Schwatzen!", completion = "Gute Arbeit, um den Rest sollten die anderen sich kümmern können. Uns bleibt noch ein letztes Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[52789] = { id = 52789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit ihrem Rat am Ende", description = "Der Schiffskapitän ist fort. Shandris und Falstad werden sich darum kümmern, ihn zu finden.\n\nWir müssen uns um die Beraterin kümmern. Kelseys Aufzeichnungen zufolge ist es eine Frau namens Ko'jan. \n\nVielleicht hat sie eine Möglichkeit, das Festland zu erreichen. Wir müssen sie erwischen, bevor sie weg ist.", sourceObjective = "Tötet Beraterin Ko'jan.", completion = "Es klingt, als hätte das Kämpfen über uns aufgehört. Dann haben Falstad und Shandris sicher den Schiffskapitän erwischt.\n\nSchauen wir mal, ob sie ihn lebendig gefangennehmen konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[52790] = { id = 52790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Töten beenden", description = "Lasst uns aufs Oberdeck zurückkehren und herausfinden, wie die Lage ist. Shandris sollte inzwischen dort sein.\n\nIch kenne Shandris und Falstad gut genug, um zu wissen, dass sie uns dort mit dem Kapitän erwarten werden, ob er nun tot sein mag oder nicht.", sourceObjective = "Trefft Shandris Mondfeder an Deck der Grals Ruf.", completion = "{name}! Ich habe gerade die Botschaft über Euren Erfolg in Zandalar erhalten. Gut gemacht.\n\nEs tut mir leid, dass Ihr für diesen Krieg so viel durchmachen musstet. Wir haben nur die eine Möglichkeit, wenn wir die Zandalari davon abhalten wollen, der Horde zu helfen.\n\nZum richtigen Zeitpunkt werden wir unsere Flotten nach Zandalar entsenden. Eure harte Arbeit wird dafür sorgen, dass es eine Lücke in ihrer Verteidigung gibt, durch die wir unsere Invasion beginnen können.\n\nIch danke Euch erneut, {name}. Wir schulden Euch und Euren Verbündeten viel.", sourceObjectiveStatus = "unverified-source-field" }
quests[52792] = { id = 52792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Akundas Biss", progress = "Wir werd'n jede Menge Kräuter brauch'n, um die Vorräte maximal aufzustock'n.", completion = "Genau das, worauf ich gehofft hab." }
quests[52793] = { id = 52793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Wagen wagen", description = "Darion und die Mädchen sollten inzwischen zurück sein.\n\nVielleicht sind sie unterwegs in Schwierigkeiten geraten. Der alte Wagen bleibt immer wieder liegen. Ich muss sichergehen, dass ihnen nichts passiert ist!\n\nKönnt Ihr für mich nach ihnen sehen?", sourceObjective = "Findet Darion, Loreen und Mallorie.", completion = "Danke. Jetzt kann ich ruhig in dem Wissen schlafen, dass sie in Sicherheit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[52794] = { id = 52794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echsen und Geschäftsbücher" }
quests[52795] = { id = 52795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da ist jemand sauer", description = "Dieser Saurolisk ist seit Jahren eine Legende in den Hügeln. \"Sauerzahn, seinen Atem riecht man meilenweit.\" \n\nHeute hat diese Legende meine Familie angegriffen und fast meinen Vater und meine Schwester getötet. Es wird Zeit, dass er stirbt.", sourceObjective = "Tötet Sauerzahn.", completion = "Jetzt riecht keiner mehr seinen Atem im Wind.", sourceObjectiveStatus = "unverified-source-field" }
quests[52796] = { id = 52796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weniger ist manchmal mehr", description = "Ich hasse Saurolisken eigentlich nicht, aber sie scheinen in letzter Zeit immer mehr zu werden.\n\nSturmsangs Militär hat früher ihre Zahl gering gehalten, aber sie sind dieses Jahr nicht aufgetaucht.\n\nVielleicht könntet Ihr die Aufgabe erledigen, die sie vernachlässigt haben?", sourceObjective = "Beseitigt 8 Saurolisken.", completion = "Danke. Jetzt kann ich ruhig in dem Wissen schlafen, dass sie in Sicherheit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[52798] = { id = 52798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch ein paar Ladungen" }
quests[52799] = { id = 52799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rudelführer", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52800] = { id = 52800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Der Aschenwindaufseher", description = "Tol Dagor ist ein gut befestigter Dorn im Auge dieser Nation.\n\nWie Ihr zweifellos wisst, hat Lady Aschenwind jede Gelegenheit genutzt, alle, die sich ihr widersetzten, in diese Zellen zu werfen. In dem Gefängnis befinden sich auch Allianzmitglieder, die mit Euch und Jaina eingetroffen sind.\n\nWir haben jetzt die Erlaubnis und die nötige Schlagkraft, um sie zu befreien. Trefft Euch mit Taelia an der Ostküste der Insel, findet den Aufseher und nehmt ihm seinen Schlüssel ab. Damit werden wir Zugang zum Waffenkeller und den Zellen erhalten.", sourceObjective = "Besorgt den Generalschlüssel von Tol Dagor von Aufseher Korgus.", progress = "Also?", completion = "Die meisten dieser Geiseln habe schon bessere Zeiten gesehen, aber sie werden sich schnell erholen. Jetzt, da Tol Dagor aus dem Weg geräumt ist, gehen Lady Aschenwind schnell die Verstecke aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[52801] = { id = 52801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Verhüllte Grotte", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf die Verhüllte Grotte geschickt.\n\nDarin steht, dass es ein hart errungener Sieg war und alle Feinde, die den Außenposten verteidigten, getötet wurden.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission nach Zuldazar?", completion = "Die Mission, in Zuldazar einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52802] = { id = 52802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verhüllte Grotte", description = "Der Überfall, den Ihr auf die Verhüllte Grotte in Zuldazar geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zur Verhüllten Grotte in Zuldazar und baut dort Befestigungsanlagen.\n\nDie Verhüllte Grotte wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Horde spielen.\n\nFür die Allianz!", sourceObjective = "Beansprucht die Verhüllte Grotte für die Allianz.", completion = "Gut gemacht, {name}. Hier ist ein ausgezeichneter Platz für einen Außenposten! Dank Eurer Führung hat die Allianz einen weiteren Stützpunkt in Zuldazar!", sourceObjectiveStatus = "unverified-source-field" }
quests[52803] = { id = 52803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versehentliche Schrecken", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52804] = { id = 52804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas regt sich in der Tiefe" }
quests[52805] = { id = 52805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Zähne ausbeißen", sourceObjective = "Tötet 25 Wendigos.", sourceObjectiveStatus = "unverified-source-field" }
quests[52806] = { id = 52806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernde Bedrohung", description = "Diese Pattsituation wird uns nichts bringen. Wir sollten uns im Bau der Schwarzfelle sammeln.", sourceObjective = "Trefft Euch mit Fürstin Sylvanas Windläufer am Bau der Schwarzfelle.", completion = "Wir müssen warten, bis Saurfang wieder zurück ist, bevor wir weitermachen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[52832] = { id = 52832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritermächtigung" }
quests[52834] = { id = 52834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des kriegsgezeichneten Schicksals: Gold", progress = "Wolltet Ihr jemals Euer Schicksal ändern? Vielleicht für eine spezielle Rüstung, eine Waffe oder ein Schmuckstück mit großer Macht?\n\nFür den richtigen Preis biete ich Euch ein Siegel an, mit dem Ihr das Schicksal wenden könnt und ein neues Ergebnis einer bereits vergangenen Chance erhaltet.\n\nSobald Ihr ein Siegel besitzt, aktiviert es sich, nachdem Ihr einen mächtigen Gegner in gefährlichen Höhlen oder Schlachtzügen getötet habt.\n\nÜberlegt Euch gut, wie Ihr bezahlen wollt, denn Ihr könnt nur zwei Siegel pro Woche bewältigen.", completion = "Eine gute Wahl. Denkt daran, nur zwei Siegel pro Woche." }
quests[52835] = { id = 52835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des kriegsgezeichneten Schicksals: Ehrenabzeichen", progress = "Wolltet Ihr jemals Euer Schicksal ändern? Vielleicht für eine spezielle Rüstung, eine Waffe oder ein Schmuckstück mit großer Macht?\n\nFür den richtigen Preis biete ich Euch ein Siegel an, mit dem Ihr das Schicksal wenden könnt und ein neues Ergebnis einer bereits vergangenen Chance erhaltet.\n\nSobald Ihr ein Siegel besitzt, aktiviert es sich, nachdem Ihr einen mächtigen Gegner in gefährlichen Höhlen oder Schlachtzügen getötet habt.\n\nÜberlegt Euch gut, wie Ihr bezahlen wollt, denn Ihr könnt nur zwei Siegel pro Woche bewältigen.", completion = "Eine gute Wahl. Denkt daran, nur zwei Siegel pro Woche." }
quests[52837] = { id = 52837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des kriegsgezeichneten Schicksals: Kriegsressourcen", progress = "Wolltet Ihr jemals Euer Schicksal ändern? Vielleicht für eine spezielle Rüstung, eine Waffe oder ein Schmuckstück mit großer Macht?\n\nFür den richtigen Preis biete ich Euch ein Siegel an, mit dem Ihr das Schicksal wenden könnt und ein neues Ergebnis einer bereits vergangenen Chance erhaltet.\n\nSobald Ihr ein Siegel besitzt, aktiviert es sich, nachdem Ihr einen mächtigen Gegner in gefährlichen Höhlen oder Schlachtzügen getötet habt.\n\nÜberlegt Euch gut, wie Ihr bezahlen wollt, denn Ihr könnt nur zwei Siegel pro Woche bewältigen.", completion = "Eine gute Wahl. Denkt daran, nur zwei Siegel pro Woche." }
quests[52838] = { id = 52838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des kriegsgezeichneten Schicksals: Goldhaufen", progress = "Fordert Ihr das Schicksal wieder einmal heraus? Die Kosten sind gestiegen und ich biete andere, günstigere Wege der Bezahlung an.\n\nWenn Ihr allerdings dieses Entgelt entrichten wollt, wer bin ich, Euch davon abzuhalten?\n\nÜberlegt Euch gut, wie Ihr bezahlen wollt, denn Ihr könnt nur zwei Siegel pro Woche bewältigen.", completion = "Eine gute Wahl. Denkt daran, nur zwei Siegel pro Woche." }
quests[52839] = { id = 52839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des kriegsgezeichneten Schicksals: Zusätzliche Ehrenabzeichen", progress = "Fordert Ihr das Schicksal wieder einmal heraus? Die Kosten sind gestiegen und ich biete andere, günstigere Wege der Bezahlung an.\n\nWenn Ihr allerdings dieses Entgelt entrichten wollt, wer bin ich, Euch davon abzuhalten?\n\nÜberlegt Euch gut, wie Ihr bezahlen wollt, denn Ihr könnt nur zwei Siegel pro Woche bewältigen.", completion = "Eine gute Wahl. Denkt daran, nur zwei Siegel pro Woche." }
quests[52840] = { id = 52840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des kriegsgezeichneten Schicksals: Versteckte Kriegsressourcen", progress = "Fordert Ihr das Schicksal wieder einmal heraus? Die Kosten sind gestiegen und ich biete andere, günstigere Wege der Bezahlung an.\n\nWenn Ihr allerdings dieses Entgelt entrichten wollt, wer bin ich, Euch davon abzuhalten?\n\nÜberlegt Euch gut, wie Ihr bezahlen wollt, denn Ihr könnt nur zwei Siegel pro Woche bewältigen.", completion = "Eine gute Wahl. Denkt daran, nur zwei Siegel pro Woche." }
