quests[52850] = { id = 52850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeyos Champions von Vol'dun", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52851] = { id = 52851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Der Mugambarundblick", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf den Mugambarundblick geschickt.\n\nDarin steht, dass es ein hart errungener Sieg war und alle Feinde, die den Außenposten verteidigten, getötet wurden.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission nach Zuldazar?", completion = "Die Mission, in Zuldazar einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52852] = { id = 52852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mugambarundblick", description = "Der Überfall, den Ihr auf den Mugambarundblick in Zuldazar geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zum Mugambarundblick in Zuldazar und baut dort Befestigungsanlagen.\n\nDer Mugambarundblick wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Horde spielen.\n\nFür die Allianz!", sourceObjective = "Beansprucht den Mugambarundblick für die Allianz.", completion = "Das hier wird einen großartigen Außenposten abgeben. Er ist gut versteckt und zu Fuß beinahe unpassierbar. Die Horde wird niemals vermuten, dass wir hier unser Lager aufgeschlagen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[52855] = { id = 52855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemie ist eine ungenaue Wissenschaft", description = "Hey, hört zu.\n\nEs hat funktioniert, oder? Überwiegend. Ich meine, es IST größer geworden. Seht mich nicht so an! Gut, es gibt ein paar... seltsame Nebenwirkungen. Seit wann hat das jemals die Wissenschaft aufgehalten?\n\nAlso schön, ist ja gut!\n\nIch habe eine Idee. Geht und holt mir alles auf dieser Liste. Und beeilt Euch! Ich glaube, diese Zandalari könnten mir etwas antun, wenn Ihr... wenn WIR... das nicht in Ordnung bringen.\n\n<Alexxi kritzelt hastig eine Liste mit Zutaten und gibt sie Euch.>\n\nTut mir den Gefallen, ja?", sourceObjective = "Sammelt 1 Krone von Torcali und 8 Staubschwingenglitzern für Händler Alexxi im Kriegsbestienkral.", progress = "Diese Klauen sehen wirklich scharf aus, {name}. Habt Ihr, was ich brauche?", completion = "Puh! Vielleicht wird sie das beruhigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52856] = { id = 52856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen auf einer Terrasse", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52857] = { id = 52857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur weiteren Beobachtung festgehalten", description = "<Händler Alexxi beeilt sich, die Zutaten zusammenzumischen.>\n\nDas müsste reichen. Geht und flößt das Eurem Terrorhorn ein.\n\nKeine Sorge, bei einer Mixtur, die unter Zwang zusammengebraut wurde, kann nichts schiefgehen. Außerdem: Sehe ich wie ein Goblin aus, der Euch etwas Gefährliches geben würde?\n\nAbsichtlich?\n\n... Nicht drauf antworten. Beeilt Euch, bevor sie mich erstechen.", sourceObjective = "Verabreicht die Arznei Eurem Terrorhorn.", completion = "<Abrichterin L'kala beäugt Alexxi misstrauisch und sieht Euch wieder an.>\n\nNichts von all dem hier war nötig. Geht. Ich brauch Zeit, um festzustell'n, was man bei Euerm Terrorhorn mach'n kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[52858] = { id = 52858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritermächtigung" }
quests[52861] = { id = 52861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lilian Voss", sourceObjective = "Ich kämpfe jetzt seit geraumer Zeit in dieser Kampagne an Eurer Seite, {name}.\n\nWir haben mit eigenen Augen gesehen, dass die Horde vor nichts zurückschreckt, wenn es darum geht, zu gewinnen. Es mag zwar nicht immer schön sein, aber am Ende haben wir die Oberhand gewonnen.\n\nIch bin gespannt, zu sehen, was Sylvanas als nächstes tut. Ich bin aber auch gespannt darauf, Euch zu beobachten.\n\nIhr seid ein ehrenhafter Mann, {name}. Gestattet mir, diesen Kampf an Eurer Seite fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
