quests[52876] = { id = 52876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlachtmetzler", description = "Auf Anordnung der Sturmwacht.\n\nSpäher haben berichtet, dass die Wissenschaftler der Verlassenen ein Monster geschaffen und aus den Leichen unserer gefallenen Soldaten zusammengenäht haben.\n\nDiese Monstrosität heißt Schlachtmetzler.\n\nDerjenige, der diese Monstrosität vernichtet, wird eine angemessene Belohnung erhalten.", sourceObjective = "Findet und tötet Schlachtmetzler.", completion = "Eine Bedrohung weniger für die Sicherheit von Sturmsang", sourceObjectiveStatus = "unverified-source-field" }
