quests[52886] = { id = 52886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Tiefgrüne Höhle", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf die Tiefgrüne Höhle geschickt.\n\nDarin steht, dass es ein hart errungener Sieg war und alle Feinde, die den Außenposten verteidigten, getötet wurden.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission nach Zuldazar?", completion = "Die Mission, in Zuldazar einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
